mapper.update:
UPDATE DAILY_MISSIONS SET status = #{status},
completed_at = CASE WHEN #{status} = 'COMPLETED' THEN CURRENT_TIMESTAMP ELSE completed_at END
WHERE daily_mission_id = #{dailyMissionId} AND user_id = #{userId}

UPDATE DAILY_MISSIONS SET status = 'EXPIRED'
WHERE user_id = #{userId} AND assigned_date < #{assignedDate}
  AND status IN ('ASSIGNED', 'FAILED')

mapper.select:
SELECT COUNT(*) FROM TRANSACTIONS WHERE user_id = #{userId}
  AND transaction_date = #{transactionDate} AND type = 'EXPENSE'
  AND category = #{category} AND amount >= 0 AND amount <= #{maxAmount}
